cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x}; shapes=[]
for r in range(4):
 for c in range(6):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if sq<=cells: shapes.append((sq,1))
  for trip in [{(r,c),(r,c+1),(r+1,c)}, {(r,c),(r,c+1),(r+1,c+1)}, {(r,c),(r+1,c),(r+1,c+1)}, {(r,c+1),(r+1,c),(r+1,c+1)}]:
   if trip<=cells: shapes.append((trip,0))
sol=[]
def rec(rem, chosen):
 if not rem: sol.append(chosen);return
 x=min(rem)
 for s,k in shapes:
  if x in s and s<=rem: rec(rem-s,chosen+[(s,k)])
